function subsets(items) {
  var result = [[]];
  items.forEach(function (item) {
    var size = result.length;
    for (var i = 0; i < size; i++) {
      result.push(result[i].concat([item]));
    }
  });
  return result;
}

console.log(subsets([1, 2, 3]));
